var deferredPrompt;
window.addEventListener('beforeinstallprompt',function(e){e.preventDefault();deferredPrompt=e;var b=document.createElement('div');b.innerHTML='<div style="position:fixed;bottom:20px;left:50%;transform:translateX(-50%);z-index:999;background:rgba(12,16,48,0.95);border:1px solid #7c6ff7;border-radius:20px;padding:16px 22px;display:flex;align-items:center;gap:14px;backdrop-filter:blur(30px);box-shadow:0 10px 40px rgba(124,111,247,0.3);max-width:500px;width:90%"><span style="font-size:2.5rem">📲</span><div style="flex:1"><h4 style="font-size:.9rem;font-weight:800;color:#fff">نصب برنامه AlexVPN</h4><p style="font-size:.72rem;color:#8080a0">با نصب برنامه، دسترسی سریع‌تر و آسان‌تری خواهید داشت</p></div><div style="display:flex;gap:8px"><button onclick="this.parentElement.parentElement.parentElement.remove();deferredPrompt.prompt();" style="padding:8px 18px;border-radius:24px;font-weight:700;font-size:.78rem;border:none;font-family:inherit;background:linear-gradient(135deg,#7c6ff7,#5b4fcf);color:#fff">نصب برنامه</button><button onclick="this.parentElement.parentElement.parentElement.remove()" style="padding:8px 18px;border-radius:24px;font-weight:700;font-size:.78rem;border:none;font-family:inherit;background:transparent;color:#8080a0;border:1px solid rgba(255,255,255,0.1)">بعداً</button></div></div>';document.body.appendChild(b);});
function showLoginAlert(){document.getElementById('loginAlert').style.display='flex'}
document.querySelectorAll('.loc-tab').forEach(t=>t.addEventListener('click',function(){document.querySelectorAll('.loc-tab').forEach(x=>x.classList.remove('active'));this.classList.add('active');document.querySelectorAll('.plans-grid').forEach(g=>g.classList.remove('active'));var g=document.querySelector('.plans-grid[data-loc="'+this.dataset.loc+'"]');if(g)g.classList.add('active')}));
function openCard(id){document.getElementById('cardPlanId').value=id;document.getElementById('cardModal').style.display='flex'}function closeCard(){document.getElementById('cardModal').style.display='none'}document.getElementById('cardModal')?.addEventListener('click',function(e){if(e.target===this)closeCard()});
function copyCardNumber(){var el=document.querySelector('.card-num');if(el){var num=el.textContent.replace(/\s/g,'');navigator.clipboard.writeText(num).then(function(){var t=document.createElement('div');t.style.cssText='position:fixed;bottom:30px;left:50%;transform:translateX(-50%);background:rgba(0,212,204,0.15);border:1px solid rgba(0,212,204,0.3);color:#00d4cc;padding:14px 28px;border-radius:36px;font-weight:700;z-index:9999;backdrop-filter:blur(20px);display:flex;align-items:center;gap:10px';t.innerHTML='<img src="/alexvpn.png" style="width:28px;height:28px;border-radius:8px;"> ✅ شماره کارت کپی شد!';document.body.appendChild(t);setTimeout(function(){t.remove()},2500)})}}
function copyTestLink(){var el=document.getElementById('testLink');if(el){navigator.clipboard.writeText(el.textContent).then(function(){var t=document.createElement('div');t.style.cssText='position:fixed;bottom:30px;left:50%;transform:translateX(-50%);background:rgba(0,212,204,0.15);border:1px solid rgba(0,212,204,0.3);color:#00d4cc;padding:14px 28px;border-radius:36px;font-weight:700;z-index:9999;backdrop-filter:blur(20px)';t.innerHTML='<img src="/alexvpn.png" style="width:28px;height:28px"> ✅ لینک تست کپی شد!';document.body.appendChild(t);setTimeout(function(){t.remove()},2500)})}}
</script>
</body></html>
